    """P = alpha*(T^T P) + (1-alpha)*restart; alpha = 1 − RESTART (или заданный alpha)."""
    if alpha is None:
        alpha = 1.0 - RESTART
    Tt = T.T.tocsr()
    P = restart_mat.copy()
